/**
 * The RESERVE collection — five looks, each a fictional garment with a
 * gradient "photograph" defined entirely in CSS (see styles.css). The look
 * book crossfades through them in the pinned section. No raster imagery.
 *
 * `swatch` is a CSS class applied to the gradient frame; the gradient itself
 * lives in styles.css so the visual stays in the stylesheet (where all
 * palette tokens live) and the data stays in the DOM.
 */
export type Look = {
  id: string;
  no: string;
  name: string;
  nameKo: string;
  fabric: string;
  fabricKo: string;
  line: string;
  lineKo: string;
  /** CSS class on the gradient frame — defines the "photograph". */
  swatch: string;
};

export const LOOKS: Look[] = [
  {
    id: "silk",
    no: "01",
    name: "Silk Shift",
    nameKo: "실크 쉬프트",
    fabric: "triple-crepe silk",
    fabricKo: "트리플 크레이프 실크",
    line: "A column of bone silk, cut on the cross, that forgets the body by noon.",
    lineKo: "뼛빛 실크의 단면. 정오가 되면 몸을 잊는다.",
    swatch: "atelier-look__art--silk",
  },
  {
    id: "wool",
    no: "02",
    name: "Wool Notch",
    nameKo: "울 노치",
    fabric: "double-faced wool",
    fabricKo: "겉감 안감 없는 울",
    line: "Shoulder built like a doorway. The notch is the only permission it gives.",
    lineKo: "어깨는 문지방처럼. 노치만이 유일한 허락이다.",
    swatch: "atelier-look__art--wool",
  },
  {
    id: "organza",
    no: "03",
    name: "Organza Veil",
    nameKo: "오간자 베일",
    fabric: "crisp silk organza",
    fabricKo: " crisp한 실크 오간자",
    line: "Two layers of organza over nothing — the garment is the light it admits.",
    lineKo: "아무것도 입지 않은 위의 오간자 두 겹 — 옷은 들여보내는 빛이다.",
    swatch: "atelier-look__art--organza",
  },
  {
    id: "trench",
    no: "04",
    name: "The Trench",
    nameKo: "트렌치",
    fabric: "waxed cotton, gold seam",
    fabricKo: "왁스 가공 코튼, 골드 솔기",
    line: "A trench cut for rain it will never see. One seam, in gold, remembers why.",
    lineKo: "다시는 보지 못할 비를 위해 깎은 트렌치. 골드 솔기 하나가 그 까닭을 기억한다.",
    swatch: "atelier-look__art--trench",
  },
  {
    id: "gown",
    no: "05",
    name: "Closing Gown",
    nameKo: "피날레 가운",
    fabric: "matte crêpe, paper spine",
    fabricKo: "무광 크레이프, 종이 등골",
    line: "Near-black, with a spine of paper-white. The collection's last word, set down softly.",
    lineKo: "거의 검정, 그 위로 종이빛 등골 하나. 컬렉션의 마지막 말을, 조용히 내려놓는다.",
    swatch: "atelier-look__art--gown",
  },
];

"use client";

import type { CSSProperties } from "react";
import { useMasthead } from "../hooks/useMasthead";

const MASTHEAD = ["A", "T", "E", "L", "I", "E", "R"];
const KOREAN = "아 틀 리 에";

/**
 * The cover. A near-black field with a faint paper wash, the maison name set
 * across the full width in oversized Bodoni, and a single gold hairline
 * beneath it — the only gold on the cover. The name reveals per glyph: each
 * letter is an `aria-hidden` span behind the h1's `aria-label`, lifted from
 * the baseline and un-clipped by a per-index stagger. The CSS default state
 * IS the finished one, so without JavaScript and under reduced motion the
 * masthead is simply there, fully set.
 *
 * Below: the season, the collection name in both languages, and the one-line
 * editor's standfirst — written as the magazine would write it, present
 * tense, no adjectives doubled, Korean transcreated (never translated).
 */
export default function Masthead() {
  const ref = useMasthead<HTMLHeadingElement>(false);

  return (
    <header className="atelier-cover" aria-labelledby="atelier-masthead">
      <div className="atelier-cover__topline">
        <span className="atelier-folio">SÉOUL · MMXXVI</span>
        <span className="atelier-folio atelier-folio--mid">
          No. 39 · RESERVE
        </span>
        <span className="atelier-folio atelier-folio--right">
          f/w · 가을/겨울
        </span>
      </div>

      <p className="atelier-cover__eyebrow" data-reveal="fade">
        The maison lookbook ·{" "}
        <span lang="ko">메종 룩북</span>
      </p>

      <h1
        id="atelier-masthead"
        ref={ref}
        className="atelier-masthead"
        aria-label="ATELIER"
      >
        {MASTHEAD.map((ch, i) => (
          <span
            key={`${ch}-${i}`}
            aria-hidden="true"
            className="atelier-masthead__ch"
            style={{ "--atelier-ci": i } as CSSProperties}
          >
            {ch}
          </span>
        ))}
      </h1>

      <p className="atelier-cover__ko" aria-hidden="true">
        {KOREAN}
      </p>

      <div className="atelier-cover__rule" aria-hidden="true" />

      <p className="atelier-cover__stand" data-reveal="fade">
        Five looks, set in silence, for the season the light turns inward.{" "}
        <span lang="ko" className="atelier-cover__standko">
          빛이 안으로 돌아드는 계절을 위해, 침묵 속에 깎은 다섯 벌.
        </span>
      </p>

      <p className="atelier-cover__scroll" aria-hidden="true">
        turn the page ↓
      </p>
    </header>
  );
}

"use client";

import { useEffect, useRef, type RefObject } from "react";

/** Frame-rate-independent smoothing per 60fps-normalized frame. */
const LERP = 0.14;
/** Frame throttle for high-refresh displays (~64fps). */
const FRAME_MS = 15.5;

/**
 * Tracks scroll progress through the pinned lookbook section and writes a
 * smoothed 0→1 value to `--atelier-page` on the pinned element.
 *
 * The lookbook is a tall section (height = LOOKS × 100vh) whose inner
 * `.atelier-lookbook__sticky` is `position: sticky; top: 0; height: 100vh`.
 * As the visitor scrolls through the runway, the five looks crossfade by
 * reading `--atelier-page` — opacity and a hairline scale only, never layout.
 *
 * This is direct input→style manipulation (scroll position → a number), not
 * an autonomous animation, so it stays live under prefers-reduced-motion —
 * only the *lerp* is bypassed there, so the page-turn still tracks the wheel
 * 1:1 and the looks still crossfade (a reveal of content, not motion).
 */
export function useLookProgress(
  pinRef: RefObject<HTMLElement | null>,
  progressVar = "--atelier-page",
): void {
  const rafRef = useRef(0);
  const smoothRef = useRef(0);
  const lastTargetRef = useRef(0);

  useEffect(() => {
    const el = pinRef.current;
    if (!el) return;
    let lastTick = 0;

    const compute = () => {
      const rect = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;
      // 0 when the section's top hits the top of the viewport,
      // 1 when its bottom hits the bottom. The section is taller than the
      // viewport on purpose (it is the pin's runway).
      const usable = Math.max(1, rect.height - vh);
      const traveled = Math.min(Math.max(-rect.top, 0), usable);
      lastTargetRef.current = traveled / usable;
      el.style.setProperty(`${progressVar}-raw`, lastTargetRef.current.toFixed(4));
    };

    const tick = (now: number) => {
      rafRef.current = 0;
      if (now - lastTick < FRAME_MS) {
        // schedule another frame to keep smoothing live without over-running
        rafRef.current = requestAnimationFrame(tick);
        return;
      }
      lastTick = now;
      smoothRef.current +=
        (lastTargetRef.current - smoothRef.current) * LERP;
      el.style.setProperty(progressVar, smoothRef.current.toFixed(4));
      // keep ticking until settled, so the page never stops mid-turn
      if (Math.abs(lastTargetRef.current - smoothRef.current) > 0.0005) {
        rafRef.current = requestAnimationFrame(tick);
      }
    };

    const schedule = () => {
      compute();
      if (!rafRef.current) {
        rafRef.current = requestAnimationFrame(tick);
      }
    };

    compute();
    smoothRef.current = lastTargetRef.current; // no spring on first paint
    el.style.setProperty(progressVar, smoothRef.current.toFixed(4));

    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule, { passive: true });
    return () => {
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [pinRef, progressVar]);
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Drives the cover masthead's per-glyph reveal — the signature
 * `char-split-reveal`. On mount (motion allowed) it adds `is-set` to the
 * referenced heading; the per-glyph CSS transition (lifted from the baseline,
 * un-clipped) is staggered by each span's `--atelier-ci`, so the masthead
 * opens like a cover being set down on a table. The CSS default state IS the
 * finished one, so without JavaScript and under reduced motion the name is
 * simply there, fully set.
 *
 * A small `requestAnimationFrame` deferral ensures the browser has painted
 * the initial (clipped) state before we flip to the final one — without it,
 * some engines fold the two states and skip the transition entirely.
 */
export function useMasthead<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (disabled) {
      el.classList.add("is-set");
      return;
    }
    const raf = requestAnimationFrame(() => {
      // double-rAF: commit the pre-state on one frame, flip on the next, so
      // the transition is guaranteed to fire across engines.
      requestAnimationFrame(() => el.classList.add("is-set"));
    });
    return () => cancelAnimationFrame(raf);
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Reveals descendants marked with [data-reveal] as they enter the viewport,
 * by adding an `is-visible` class. Pre-reveal states (opacity/translate for
 * "fade", the rising inset clip for "clip") live in styles.css and are gated
 * behind the `.atelier-js` root class, so all content is fully visible when
 * JavaScript never runs.
 *
 * Elements that intersect in the same observer batch are staggered 80ms
 * apart — the magazine cadence. The delay is written both as transition-delay
 * (for the element itself) and as `--atelier-reveal-delay`, so a child — the
 * clip-path on an editorial frame — can inherit the same beat.
 */
export function useReveal<T extends HTMLElement>(disabled: boolean) {
  const rootRef = useRef<T | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const targets = Array.from(
      root.querySelectorAll<HTMLElement>("[data-reveal]"),
    );

    if (disabled || !("IntersectionObserver" in window)) {
      for (const el of targets) el.classList.add("is-visible");
      return;
    }

    const io = new IntersectionObserver(
      (hits) => {
        let batch = 0;
        for (const hit of hits) {
          if (!hit.isIntersecting) continue;
          const el = hit.target as HTMLElement;
          const delay = `${batch * 80}ms`;
          el.style.transitionDelay = delay;
          el.style.setProperty("--atelier-reveal-delay", delay);
          el.classList.add("is-visible");
          io.unobserve(el);
          batch += 1;
        }
      },
      { threshold: 0.16, rootMargin: "0px 0px -8% 0px" },
    );
    for (const el of targets) io.observe(el);
    return () => io.disconnect();
  }, [disabled]);

  return rootRef;
}

"use client";

import { useEffect, useRef } from "react";
import "./styles.css";
import { bodoni, notoSerifKr } from "./fonts";
import Masthead from "./components/Masthead";
import Manifesto from "./components/Manifesto";
import Lookbook from "./components/Lookbook";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";
import { useReveal } from "./hooks/useReveal";

/**
 * ATELIER — high-fashion maison, the RESERVE collection. The page is a
 * magazine cover made interactive: oversized Bodoni, expensive silence, one
 * rare antique-gold accent. Where ONDO is a single perfume bottle, ATELIER is
 * a full collection lookbook — the editorial-spread-as-website.
 *
 * `.atelier-js` is added imperatively on mount (a signal to CSS that JS is
 * alive, never React state): every pre-reveal style is gated behind it, and
 * with JavaScript off the full lookbook simply stands finished.
 */
export default function AtelierPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>(reduced);

  useEffect(() => {
    rootRef.current?.classList.add("atelier-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "atelier" }, "*");
  }, []);

  return (
    <div
      ref={rootRef}
      className={`${bodoni.variable} ${notoSerifKr.variable} atelier-root`}
    >
      <div ref={revealRef} className="atelier-doc">
        <Masthead />
        <main>
          <Manifesto />
          <Lookbook />
        </main>
        <footer className="atelier-foot">
          <p className="atelier-foot__brand">
            ATELIER <span lang="ko">아틀리에</span>
          </p>
          <p className="atelier-foot__line">
            <span lang="ko">RESERVE 2026 — 한 벌 한 벌, 손으로.</span>{" "}
            RESERVE 2026 — one at a time, by hand.
          </p>
          <p className="atelier-foot__copy">
            © 2026 ATELIER · <span lang="ko">서울</span> Seoul
          </p>
        </footer>
      </div>
    </div>
  );
}

/* ==========================================================================
   ATELIER — high-fashion maison · the RESERVE collection
   luxury-fashion · black / off-white / one antique-gold accent
   Scoped by convention to .atelier-root; classes prefixed atelier-.
   ========================================================================== */

.atelier-root {
  --at-black: #0a0a0a;
  --at-paper: #f8f6f2;
  --at-ink-soft: #6b6660;
  --at-gold: #b8945a;
  --at-hairline: rgba(10, 10, 10, 0.14);

  --at-font-latin: var(--font-bodoni), "Bodoni Moda", serif;
  --at-font-kr: var(--font-noto-serif-kr), "Noto Serif KR", serif;
  --at-font-stack: var(--font-bodoni), var(--font-noto-serif-kr), serif;

  --at-ease: cubic-bezier(0.16, 1, 0.3, 1);
  --at-reveal-ms: 1200ms;

  position: relative;
  min-height: 100vh;
  background: var(--at-paper);
  color: var(--at-black);
  font-family: var(--at-font-stack);
  font-weight: 400;
  font-size: clamp(16px, 0.5vw + 14px, 18px);
  line-height: 1.7;
  overflow-x: hidden;
  overflow-x: clip;
}

.atelier-root :lang(ko) {
  font-family: var(--at-font-kr);
  letter-spacing: 0.01em;
}

.atelier-root ::selection {
  background: var(--at-black);
  color: var(--at-paper);
}

.atelier-root :focus-visible {
  outline: 1px solid var(--at-gold);
  outline-offset: 6px;
}

.atelier-doc {
  position: relative;
  z-index: 1;
}

/* ---- Reveal gating (JS-dependent pre-states) ---- */
.atelier-js [data-reveal] {
  opacity: 0;
  transform: translateY(28px);
  transition:
    opacity var(--at-reveal-ms) var(--at-ease),
    transform var(--at-reveal-ms) var(--at-ease);
}
.atelier-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* ---- Typography ---- */
.atelier-root h1,
.atelier-root h2 {
  font-family: var(--at-font-latin);
  font-weight: 500;
  line-height: 0.95;
  letter-spacing: -0.02em;
}

@media (prefers-reduced-motion: reduce) {
  .atelier-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }
}
